-- Mensaje 104 · Dos «no» seguidos en toda la visita y tres solo en el cierre; qué es un «no»; el hueco en no_aplica si no lo había;
-- insistir tras dos no en los bosses; el 7.4 sin bloqueo doble (Emilio, 21 y 28-oct-2026).
-- Primero el Cerebro, luego las reglas, luego los guiones. Todo protegido: si algo no está como se espera, no cambia; el chequeo final aborta si algo no quedó.
DO $c$ DECLARE v int; BEGIN
  IF EXISTS (SELECT 1 FROM public.doctrina WHERE is_active AND body LIKE '%**Qué es un «no»**%') THEN
    RAISE NOTICE 'El Cerebro ya tiene los cambios del 104: no se crea otra versión.'; RETURN;
  END IF;
  SELECT max(version) INTO v FROM public.doctrina WHERE is_active;
  IF (SELECT count(*) FROM public.doctrina WHERE version = v AND strpos(body, $v$**Dos no seguidos en la puerta** `CAMPO`: si haces AIR y el cliente repite el bloqueo de inmediato, ya son dos no seguidos. Ahí lo correcto es quedar de regresar en otro momento, con una alternativa concreta: *"¿le queda mejor que pase el jueves o el viernes?"*. Insistir más ya no es seguridad: es terquedad. Tienen que ser consecutivos: si la conversación avanzó entre uno y otro, el primero ya quedó atrás. En el cierre la regla es otra (ver La Regla de los No).$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro vigente no tiene el texto esperado: %', $v$**Dos no seguidos en la puerta** `CAMPO`: si haces AIR y el cliente re$v$; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE version = v AND strpos(body, $v$- **Esta regla es del cierre.** En los bloqueos de la puerta son **dos** no seguidos y quedas de regresar (ver AIR).$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro vigente no tiene el texto esperado: %', $v$- **Esta regla es del cierre.** En los bloqueos de la puerta son **dos$v$; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE version = v AND strpos(body, $v$> **La línea que no se cruza:** un hueco tiene que ser real y verificable. **Descubrir un hueco es señalar algo que ya existe. Fabricarlo es venderle un problema que no tiene.**$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro vigente no tiene el texto esperado: %', $v$> **La línea que no se cruza:** un hueco tiene que ser real y verifica$v$; END IF;
  INSERT INTO public.doctrina (version, section_key, order_index, title, body, is_active, created_by)
  SELECT v + 1, section_key, order_index, title, replace(replace(replace(body, $v$**Dos no seguidos en la puerta** `CAMPO`: si haces AIR y el cliente repite el bloqueo de inmediato, ya son dos no seguidos. Ahí lo correcto es quedar de regresar en otro momento, con una alternativa concreta: *"¿le queda mejor que pase el jueves o el viernes?"*. Insistir más ya no es seguridad: es terquedad. Tienen que ser consecutivos: si la conversación avanzó entre uno y otro, el primero ya quedó atrás. En el cierre la regla es otra (ver La Regla de los No).$v$, $v$**Dos no seguidos** `CAMPO`: en cualquier momento de la visita, menos en el cierre, dos «no» seguidos son la señal de que hoy no es el día, y lo correcto es dejarlo para otra visita. En la puerta: si haces AIR y el cliente repite el bloqueo de inmediato, ya son dos no seguidos. Ahí lo correcto es quedar de regresar en otro momento, con una alternativa concreta: *"¿le queda mejor que pase el jueves o el viernes?"*. Insistir más ya no es seguridad: es terquedad. Al buscar el hueco es igual: si dos intentos seguidos se topan con un «no», dejas de buscar y lo retomas en otra visita. Tienen que ser consecutivos: si la conversación avanzó entre uno y otro, el primero ya quedó atrás. En el cierre la regla es otra: son tres (ver La Regla de los No).

**Qué es un «no»** `CAMPO`: una respuesta que rechaza lo que el vendedor estaba intentando en ese momento —seguir la plática, explorar ese tema o avanzar a la decisión—, aunque traiga excusa. Una respuesta, aunque sea vaga o corta, no es un «no»: no rechazó nada, y lo que toca es seguir. Una duda, una condición o una objeción tampoco es un «no»: es una objeción, y se trabaja con sus herramientas.$v$), $v$- **Esta regla es del cierre.** En los bloqueos de la puerta son **dos** no seguidos y quedas de regresar (ver AIR).$v$, $v$- **Esta regla es del cierre.** En cualquier otro momento de la visita son **dos** no seguidos: en la puerta quedas de regresar, y al buscar el hueco lo dejas para otra visita (ver Dos no seguidos, en AIR).$v$), $v$> **La línea que no se cruza:** un hueco tiene que ser real y verificable. **Descubrir un hueco es señalar algo que ya existe. Fabricarlo es venderle un problema que no tiene.**$v$, $v$> **La línea que no se cruza:** un hueco tiene que ser real y verificable. **Descubrir un hueco es señalar algo que ya existe. Fabricarlo es venderle un problema que no tiene.**

**Si no hay hueco** `CAMPO`: si lo buscaste bien —con las herramientas, y siguiendo las respuestas vagas— y no apareció, o te topaste con dos «no» seguidos, hoy no había nada que descubrir. No es una falla: lo retomas en otra visita.$v$), true, created_by
  FROM public.doctrina WHERE version = v;
  UPDATE public.doctrina SET is_active = false WHERE is_active AND version = v;
END $c$;

INSERT INTO public.reglas (id, paso, tipo, canal, procedencia, resumen, cita_cerebro, severidad_default) VALUES ('flow.dos_no_seguidos', 0, 'principio', 'universal', 'CAMPO', $v$En cualquier momento de la visita, menos en el cierre, dos «no» seguidos son la señal de que hoy no es el día: se deja para otra visita (en la puerta, quedar de regresar con una alternativa concreta; al buscar el hueco, dejar de buscar). En el cierre son tres: la Regla de los No. LA PRUEBA DE UN «NO»: ¿la respuesta del cliente rechaza lo que el vendedor estaba intentando en ese momento —seguir la plática, explorar ese tema o avanzar a la decisión—, aunque traiga excusa? Entonces es un «no». Si contesta, aunque sea vago o corto, no es un «no». Si pone una duda, una condición o una objeción, tampoco: es una objeción. Seguidos: entre uno y otro la conversación no avanzó.$v$, $v$menos en el cierre, dos «no» seguidos son la señal de que hoy no es el día$v$, NULL) ON CONFLICT (id) DO NOTHING;
UPDATE public.reglas SET resumen = $v$Tres no CONSECUTIVOS y sigues adelante. La racha se rompe si la conversación avanza. Solo en el cierre: en cualquier otro momento de la visita son dos (flow.dos_no_seguidos).$v$, updated_at = now() WHERE id = 'objection.regla_de_los_no' AND resumen = $v$Tres no CONSECUTIVOS y sigues adelante. La racha se rompe si la conversación avanza.$v$;
UPDATE public.reglas SET resumen = $v$La Regla de los No: tres 'no' CONSECUTIVOS son luz roja (la fuente dice dos; Emilio usa tres, porque hay quien deja ir un sí solo porque el cliente tuvo objeciones). Con la luz roja, el vendedor sale rápido y bien: sin insistir, cuidando la relación y dejando una siguiente cita. Tienen que ser seguidos: si la conversación avanzó entre un no y otro, la racha se rompe. Salir así es la ejecución correcta, no una falta. Esta regla es del cierre: en cualquier otro momento de la visita son dos no seguidos (flow.dos_no_seguidos).$v$, updated_at = now() WHERE id = 'objections.regla_de_los_no' AND resumen = $v$La Regla de los No: tres 'no' CONSECUTIVOS son luz roja (la fuente dice dos; Emilio usa tres, porque hay quien deja ir un sí solo porque el cliente tuvo objeciones). Con la luz roja, el vendedor sale rápido y bien: sin insistir, cuidando la relación y dejando una siguiente cita. Tienen que ser seguidos: si la conversación avanzó entre un no y otro, la racha se rompe. Salir así es la ejecución correcta, no una falta.$v$;
UPDATE public.reglas SET resumen = $v$El hueco es algo que el cliente podría comprarte y no te compra: una familia que le compra a otro proveedor, una que le piden y no maneja, o una que no maneja nadie. No tiene señal verbal: se ve o se pregunta. Tiene que ser real y verificable: lo viste, te lo dijo, o lo sabes por su giro. LA PRUEBA: al terminar la plática, ¿quedó al descubierto al menos un hueco concreto —una familia con nombre— porque el vendedor lo preguntó, lo vio, lo ancló en negocios como el suyo, o el cliente lo dijo? Si sí, cumple, aunque el vendedor no lo mencione: el hueco se descubre y se apunta para usarlo en la presentación. No basta con preguntar si la respuesta no dejó ninguna familia concreta. Ofrecérselo o decirle por qué le conviene no se pide aquí: eso es presentar el hueco (paso 4). Si el vendedor lo buscó bien —usó las herramientas y siguió las respuestas vagas— o salió después de dos «no» seguidos, y no apareció ningún hueco, el criterio es no_aplica: hoy no había nada que descubrir.$v$, updated_at = now() WHERE id = 'discovery.hueco' AND resumen = $v$El hueco es algo que el cliente podría comprarte y no te compra: una familia que le compra a otro proveedor, una que le piden y no maneja, o una que no maneja nadie. No tiene señal verbal: se ve o se pregunta. Tiene que ser real y verificable: lo viste, te lo dijo, o lo sabes por su giro. LA PRUEBA: al terminar la plática, ¿quedó al descubierto al menos un hueco concreto —una familia con nombre— porque el vendedor lo preguntó, lo vio, lo ancló en negocios como el suyo, o el cliente lo dijo? Si sí, cumple, aunque el vendedor no lo mencione: el hueco se descubre y se apunta para usarlo en la presentación. No basta con preguntar si la respuesta no dejó ninguna familia concreta. Ofrecérselo o decirle por qué le conviene no se pide aquí: eso es presentar el hueco (paso 4).$v$;
UPDATE public.reglas SET resumen = $v$Levantar el pedido de siempre y despedirse sin explorar nada. Al que solo toma pedidos lo reemplaza un formulario. LA PRUEBA: ¿el vendedor se fue con el pedido sin haber descubierto algo más y sin haberlo intentado de verdad? Intentarlo es usar al menos una de las herramientas del hueco —mapear qué otras líneas maneja y con quién, preguntar qué le piden que no tenga, o anclar en negocios como el suyo— y, si la respuesta es vaga («de todo un poco», «lo normal»), seguir: con opciones concretas o con otra herramienta. Una sola pregunta al aire y despedirse después de una respuesta vaga es trámite. Si descubrió algo más, o lo intentó así, no es esto. Dejar de buscar después de dos «no» seguidos no es trámite: es lo correcto (flow.dos_no_seguidos).$v$, updated_at = now() WHERE id = 'develop.visita_tramite' AND resumen = $v$Levantar el pedido de siempre y despedirse sin explorar nada. Al que solo toma pedidos lo reemplaza un formulario. LA PRUEBA: ¿el vendedor se fue con el pedido sin haber descubierto algo más y sin haberlo intentado de verdad? Intentarlo es usar al menos una de las herramientas del hueco —mapear qué otras líneas maneja y con quién, preguntar qué le piden que no tenga, o anclar en negocios como el suyo— y, si la respuesta es vaga («de todo un poco», «lo normal»), seguir: con opciones concretas o con otra herramienta. Una sola pregunta al aire y despedirse después de una respuesta vaga es trámite. Si descubrió algo más, o lo intentó así, no es esto.$v$;
UPDATE public.reglas SET severidad_default = 'major', updated_at = now() WHERE id = 'blocks.insistir_tras_dos_no' AND severidad_default = 'critical';

UPDATE public.nodes SET practice_script = $g${"notes": "v1.0.0 Dos no seguidos en la puerta (Emilio, 15-oct-2026). El primer bloqueo se pasa con AIR; el segundo, seguido, ya es un hoy no: se queda de regresar o se despide con amabilidad. El espejo ensena: si insiste, el cliente se cierra; si se va bien, queda la puerta abierta.", "scope": {"skills_in_focus": ["blocks.air", "blocks.dos_no_seguidos"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 5, "max_duration_seconds": 180, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Me van a bloquear dos veces seguidas.\n\nAl primero le hago AIR: lo acepto, no lo discuto y sigo con lo mio.\n\nAl segundo ya no insisto: hoy no es el dia. Quedo de regresar, con dos opciones de dia, o me despido con amabilidad.", "first_message": "Claro, se ve que hoy esta a tope. Le queda mejor que pase el jueves o el viernes en la manana?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\n\nEres el encargado de un negocio y hoy de verdad andas a tope. En tu PRIMERA respuesta, sin importar lo que diga el vendedor, sueltas un bloqueo de reflejo, con naturalidad y sin agresion: ahorita ando ocupado / no me interesa, gracias / no estoy comprando nada. DESPUES REACCIONAS ASI: 1) Si el vendedor ACEPTA tu bloqueo sin pelearlo y sigue con su tema (hace AIR), en tu SEGUNDA respuesta repites el bloqueo de inmediato, mas firme pero amable, porque hoy de verdad no puedes: de verdad, ahorita no puedo, ando a tope. 2) Si despues de ese segundo bloqueo el vendedor queda de regresar otro dia o se despide con amabilidad, aceptas con gusto y te despides bien (si, el jueves esta bien, pasele), y ahi termina. 3) Si despues del segundo bloqueo el vendedor SIGUE insistiendo (nomas un minutito, dejeme le explico, vuelve a preguntar de su tema), te molestas: contestas seco y lo despachas. 4) Si el vendedor DISCUTE tu primer bloqueo o intenta convencerte de que si te interesa, te cierras de verdad y lo despachas. 5) Si el vendedor se disculpa o se va con el primer bloqueo, lo dejas ir sin insistir. NUNCA cambias de opinion despues del segundo bloqueo: hoy no puedes. Responde en 1 o 2 frases.", "objective": "El vendedor pasa el primer bloqueo con AIR y, ante el segundo bloqueo seguido, no insiste: queda de regresar en otro momento o se despide con amabilidad. El scope se cubre cuando el vendedor ya respondio al segundo bloqueo."}, "closing": {"message": "Eso es leer bien el momento. Pasaste el primer no con AIR, y al segundo no insististe: te fuiste bien y la puerta queda abierta para la siguiente visita. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose y te digo como quedaron esos dos no."}}, "version": "1.0.5", "i_do_type": "demo", "failure_criteria": [{"id": "insiste_tras_dos", "regla_id": "blocks.insistir_tras_dos_no", "severity": "critical", "description": "Despues del segundo bloqueo seguido sigue insistiendo: pide un minutito, vuelve a su tema o trata de convencerlo. Ya no es seguridad, es terquedad, y el cliente lo recibe cerrado la proxima vez. Solo cuenta lo que el vendedor dice DESPUES del segundo bloqueo: si todavia no ha contestado al segundo bloqueo, esta falla no aplica.", "severity_override": {"razon": "escalada: es lo que enseña este nodo", "default": "major"}}, {"id": "discute_el_bloqueo", "regla_id": "blocks.discute_bloqueo", "severity": "critical", "description": "Intenta convencer al cliente de que si le interesa o de que si tiene tiempo. Convierte un reflejo en una posicion, y ahora si tiene un no de verdad enfrente."}, {"id": "se_va_al_primero", "regla_id": "blocks.se_rinde_al_bloqueo", "severity": "critical", "description": "Ante el PRIMER bloqueo se disculpa, se despide o promete volver despues, sin intentar AIR. Se rindio ante un reflejo que no significaba nada. Quedar de regresar es correcto solo despues del segundo bloqueo seguido."}, {"id": "pide_permiso_de_nuevo", "regla_id": "blocks.air_sin_resume", "severity": "major", "description": "Acepta el primer bloqueo pero despues pide autorizacion para seguir. Le devuelve el control al cliente justo despues de haberlo recuperado."}, {"id": "se_va_con_disculpa", "regla_id": "opening.se_disculpa", "severity": "minor", "description": "Se despide despues del segundo bloqueo, pero pidiendo perdon por haberlo molestado (perdon por quitarle su tiempo, disculpe la molestia). Se hace menos: trae algo que le puede servir y no tiene por que disculparse.", "severity_override": {"razon": "incidental: fuera del foco del nodo", "default": "critical"}}], "success_criteria": [{"id": "blocks.air", "weight": 0.4, "regla_id": "blocks.air", "description": "Pasa el PRIMER bloqueo con los tres movimientos: lo ACEPTA con un entiendo, claro que si o por supuesto; NO lo discute ni se justifica; y SIGUE con la plática con naturalidad (con otra pregunta o con lo que iba a decir), sin pedir permiso otra vez."}, {"id": "blocks.dos_no_seguidos", "weight": 0.6, "regla_id": "blocks.dos_no_seguidos", "description": "Ante el SEGUNDO bloqueo seguido, no insiste: queda de regresar en otro momento (mejor con dos opciones de dia, como jueves o viernes) o se despide con amabilidad. Cualquiera de las dos cumple. Si sigue insistiendo, no cumple. Si el vendedor se fue con el primer bloqueo, el cliente nunca repitio el bloqueo: este criterio es no_aplica, no cumple."}]}$g$::jsonb WHERE id = '2.7c' AND practice_script->>'version' = '1.0.4';
UPDATE public.nodes SET practice_script = $g${"notes": "v2.0.0 BOSS del Mundo 2. Sin pistas garantizadas (R9). Acumulativo: el Mundo 1 se examina implicitamente porque una apertura mal hecha no abre la conversacion. La senal de exito es que el cliente pregunte en que le puede servir, que es la puerta al Descubrimiento.", "scope": {"skills_in_focus": ["blocks.air", "story.historia_breve", "story.brevedad", "relationship.cpr", "flow.close_with_action", "story.relevancia_cliente"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 12, "max_duration_seconds": 300, "min_turns_before_evaluation": 4}, "phases": {"i_do": {"briefing": "Este es el examen del mundo. Bloqueo de entrada, historia breve, relacion personal y seguir avanzando: todo junto y con un cliente que no ayuda.\n\nSin pistas.", "first_message": "Entiendo perfecto, no se preocupe. Soy Emilio, ando trabajando con los negocios de esta zona y quise pasar a conocer el suyo.\n\nDigame una cosa, cuanto tiempo lleva usted aqui?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\n\nEres el encargado de un negocio, ocupado y con poca paciencia para vendedores. En tu PRIMERA respuesta sueltas un bloqueo de reflejo, con naturalidad y sin agresion: ahorita ando ocupado / no me interesa / no estoy comprando nada. TU COMPORTAMIENTO: eres cortes pero cerrado y contestas corto. NO ofreces informacion y NO llevas la conversacion. REGLAS DE REACCION: 1) Si el vendedor pelea el bloqueo, se disculpa o se va, lo despachas y la conversacion termina. 2) Si lo acepta y sigue, continuas con naturalidad. 3) Si su historia breve se alarga mas de tres o cuatro frases, te desconectas: contestas ajam y dices que andas ocupado. 4) Si el vendedor resuelve algo y se queda callado esperando, TU tomas el control y empiezas a despedirte con amabilidad. 5) En tu tercera o cuarta respuesta, si la conversacion sigue viva, sueltas de manera natural UN dato personal tuyo, al pasar, sin darle importancia: elige entre familia, como empezaste, que haces los domingos, por que pusiste el negocio, o tu equipo. Si el vendedor lo ignora, te enfrias y ya no ofreces nada mas de ti. Si le entra con interes real, te abres notablemente. Si se queda platicando de eso mas de dos intercambios sin volver al negocio, te acomodas a platicar de la vida y ya nunca regresas tu al tema. 6) SOLO si el vendedor logra todo — atravesar el bloqueo, decir quien es breve y relevante, conectar contigo como persona y regresar, y avanzar sin pedir permiso — entonces te abres de verdad: le cuentas algo de tu negocio por tu cuenta y le preguntas en que le puede servir. Esa pregunta es la senal de que gano. NUNCA la hagas antes de que se lo gane. Responde en 1 o 2 frases.", "objective": "El vendedor atraviesa el bloqueo inicial, se presenta en quince segundos de forma relevante, conecta con el dato personal y regresa, y sostiene el avance sin pedir permiso. El scope se cubre cuando el cliente se abre por su propia voluntad y pregunta en que le puede servir."}, "closing": {"message": "Ahi esta la puerta fria abierta. Atravesaste el bloqueo sin pelearlo, dijiste quien eras sin cansarlo, conectaste como persona y volviste, y nunca soltaste el control de la conversacion. Ese cliente ya quiere saber en que le puedes servir, y eso es exactamente lo que sigue. Vamos al detalle.", "message_incomplete": "Hasta aqui la sesion. Ya tengo lo que necesito para tu analisis. Vamos al desglose y te digo donde estuvo la diferencia."}}, "version": "2.1.4", "i_do_type": "demo", "failure_criteria": [{"id": "discute_el_bloqueo", "regla_id": "blocks.discute_bloqueo", "severity": "critical", "description": "Pelea el bloqueo inicial o intenta convencer al cliente de que si le interesa."}, {"id": "se_disculpa_o_se_va", "regla_id": "blocks.se_rinde_al_bloqueo", "severity": "critical", "description": "Ante el bloqueo, se disculpa, se despide o promete volver despues. Si el cliente REPITE el bloqueo justo despues del AIR (dos no seguidos), quedar de regresar en otro momento es lo correcto y no es esta falla."}, {"id": "se_queda_esperando", "regla_id": "close.devuelve_el_volante", "severity": "critical", "description": "Resuelve algo y se queda callado esperando permiso. El cliente toma el control y se despide.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "historia_larga", "regla_id": "story.kill", "severity": "major", "description": "La historia breve se extiende y el cliente se desconecta."}, {"id": "ignora_lo_personal", "regla_id": "story.nunca_sale", "severity": "major", "description": "Pasa de largo el dato personal que el cliente ofrecio.", "severity_override": {"razon": "boss: escalada", "default": "minor"}}, {"id": "se_queda_platicando", "regla_id": "story.sale_sin_regresar", "severity": "major", "description": "Le entra a lo personal y ya no vuelve al negocio."}, {"id": "pitch_prematuro", "regla_id": "opening.pitch_prematuro", "severity": "critical", "description": "Mete producto, promocion o motivo de venta. Identificarse con nombre y empresa es el trabajo de este paso, no una excepción: aquí SÍ se dice quién eres y por qué estás."}, {"id": "insiste_tras_dos", "regla_id": "blocks.insistir_tras_dos_no", "severity": "major", "description": "Después de dos no seguidos en la puerta sigue insistiendo: pide un minutito, vuelve a su tema o trata de convencerlo, en vez de quedar de regresar en otro momento. Ya no es seguridad, es terquedad. Solo cuenta lo que dice DESPUÉS del segundo no seguido."}], "success_criteria": [{"id": "blocks.air", "weight": 0.25, "regla_id": "blocks.air", "description": "Atraviesa el bloqueo inicial: lo acepta, no lo pelea, y sigue con la plática sin pedir permiso."}, {"id": "story.historia_breve", "weight": 0.15, "regla_id": "story.quien_eres_por_que", "description": "Dice quien es y por que esta ahi: nombre, procedencia y motivo humano de la visita."}, {"id": "story.brevedad", "weight": 0.1, "regla_id": "story.kiss", "description": "Dos o tres frases. Sin trayectoria de empresa, sin lista de productos, sin cifras."}, {"id": "relationship.cpr", "weight": 0.2, "regla_id": "relationship.cpr", "description": "Detecta el dato personal, le entra con interes genuino, y REGRESA al negocio por su cuenta en uno o dos intercambios."}, {"id": "flow.close_with_action", "weight": 0.15, "regla_id": "close_with_action", "description": "Despues de cada freno avanza por su cuenta, sin quedarse esperando ni pedir autorizacion. Sostiene el control de la conversacion toda la sesion."}, {"id": "story.relevancia_cliente", "weight": 0.15, "regla_id": "story.pregunta_despues", "description": "Sus turnos terminan devolviéndole la palabra al cliente con una pregunta: no deja afirmaciones sueltas en el aire."}]}$g$::jsonb WHERE id = '2.10' AND practice_script->>'version' = '2.1.3';
UPDATE public.nodes SET practice_script = $g${"notes": "BOSS del Mundo 3 — el más completo hasta ahora: integra M0 (apertura), M1 (temple ante sequedad analítica), M2 (historia + AIR) y M3 entero (RRR + capas + escucha + dolor). El Actor combina 4 mecánicas: estado de prisa, un bloqueo espejo, dolor por capas y datos laterales. pitch_prematuro es critical — la línea entre diagnóstico y receta es la frontera del mundo. 16 turnos y 6 mínimos: es una conversación larga de verdad.", "scope": {"skills_in_focus": ["discovery.preguntas_capas", "discovery.dolor_real", "discovery.escucha_activa", "mindset.rrr", "blocks.air", "story.historia_breve"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 16, "max_duration_seconds": 360, "min_turns_before_evaluation": 6}, "phases": {"you_do": {"prompt": "Eres el dueño de un negocio de perfil ANALÍTICO: preciso, algo reservado, respondes con datos y no con emociones, desconfías un poco de los vendedores porque varios te han hecho perder el tiempo. GUION DE LA SESIÓN: (1) Recibes la apertura con cortesía seca — hoy además andas algo APURADO (estado RRR: lo muestras en frases cortas y alguna mención de que traes pendientes). (2) En tus primeras 2-3 respuestas sueltas UN bloqueo reflejo suave: mire, la verdad ando corto de tiempo, o ya tengo con quién trabajo esto. Espejo AIR: si lo atraviesa bien, sigues; si lo debate, te enfrías. (3) Tienes un DOLOR REAL oculto — elige al azar: (tu proveedor actual te deja plantado con los pedidos cada quincena / tienes producto parado que no se mueve y te tiene el dinero muerto / te piden algo que tu proveedor no maneja). Lo revelas SOLO por capas: hechos → pista sutil en capa de experiencia (la palabra aunque) → dolor completo si excavan la pista. (4) MECÁNICA DE ESCUCHA: en tus respuestas de hechos regala UN dato lateral (un familiar en el negocio, un cambio reciente); si lo recogen, te abres más rápido — la capa 2 llega antes. (5) Si el vendedor lee tu prisa y la reconoce ajustando su ritmo, cooperas mejor. Si presenta producto en cualquier momento, te cierras con evasiva educada y la información se acaba. Tu techo emocional: cooperativo-interesado, nunca efusivo. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.\n\nREGLA DE OPCIONES SUGERIDAS: si el vendedor hace una pregunta y ADEMAS te avienta tres o cuatro opciones concretas (que familias manejas? anticongelantes? aceite de motor?, o a como lo compras? 70? 80? 90?), contestas de inmediato con un dato ESPECIFICO — o eliges una de sus opciones, o lo corriges con la cifra o el producto real. Nunca contestas pues no se a una pregunta con opciones. Si te hace una pregunta abierta sin opciones y no tienes el dato a la mano, SI puedes contestar vago.", "objective": "El vendedor completa el diagnóstico de punta a punta ante un cliente analítico y apurado: apertura correcta y calibrada, historia breve corta con gancho, UN bloqueo atravesado con AIR, lectura del estado (prisa) reconocida y ajustada, descubrimiento por capas que recoge las pistas laterales y excava la pista del dolor hasta la revelación completa, cerrando con la confirmación verbal del dolor en palabras propias (entonces lo que más le está pegando es X, ¿cierto?). El scope se cubre cuando el dolor real quedó revelado por el cliente Y confirmado por el vendedor."}, "closing": {"message": "Diagnóstico completo: abriste, atravesaste el no, leíste su prisa, y excavaste hasta el dolor que no le cuenta a cualquiera. Un doctor de verdad. Vamos al desglose del mundo.", "message_incomplete": "Hasta aqui la sesion — un diagnostico de verdad no siempre se termina, pero siempre ensena. Vamos al desglose y te digo exactamente donde quedo la excavacion."}}, "version": "1.0.2", "i_do_type": "demo", "failure_criteria": [{"id": "pitch_prematuro", "regla_id": "discovery.receta_sin_diagnostico", "severity": "critical", "description": "Presenta producto en cualquier punto — incluso al descubrir el dolor. El diagnóstico termina donde empieza la receta, y la receta es del siguiente mundo.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "ignora_pistas", "regla_id": "discovery.escalera_capas", "severity": "major", "description": "Deja pasar la pista del dolor (el aunque) o los datos laterales de forma sistemática.", "espejo_de": "discovery.preguntas_capas"}, {"id": "debate_bloqueo", "regla_id": "blocks.discute_bloqueo", "severity": "critical", "description": "Argumenta o negocia el bloqueo en lugar de atravesarlo con AIR.", "severity_fix": "major->critical (BOSS no baja errores de su paso)"}, {"id": "ignora_estado", "regla_id": "discovery.rrr", "severity": "major", "description": "El cliente muestra prisa clara y el vendedor avanza a su ritmo propio sin reconocerla ni ajustar.", "espejo_de": "mindset.rrr"}, {"id": "interrogatorio", "regla_id": "discovery.interrogatorio", "severity": "minor", "description": "Ráfagas de preguntas desconectadas de las respuestas."}, {"id": "kill_curriculum", "regla_id": "story.kill_curriculum", "severity": "minor", "description": "Historia breve inflada con credenciales.", "severity_override": {"razon": "incidental: error de otro paso", "default": "major"}}, {"id": "monologo", "regla_id": "monologo", "severity": "minor", "description": "Turnos largos ante un cliente con prisa."}, {"id": "insiste_tras_dos", "regla_id": "blocks.insistir_tras_dos_no", "severity": "major", "description": "Después de dos no seguidos en la puerta sigue insistiendo: pide un minutito, vuelve a su tema o trata de convencerlo, en vez de quedar de regresar en otro momento. Ya no es seguridad, es terquedad. Solo cuenta lo que dice DESPUÉS del segundo no seguido."}], "success_criteria": [{"id": "discovery.preguntas_capas", "weight": 0.25, "regla_id": "discovery.escalera_capas", "description": "Descubrimiento con progresión de capas visible: hechos → experiencia → excavación de la pista (aunque...) hasta el dolor. Las preguntas nacen de las respuestas."}, {"id": "discovery.dolor_real", "weight": 0.2, "regla_id": "discovery.confirmacion_con_sus_palabras", "description": "El dolor completo fue revelado por el cliente Y confirmado verbalmente por el vendedor en sus propias palabras antes del cierre de la sesión."}, {"id": "discovery.escucha_activa", "weight": 0.15, "regla_id": "discovery.escalera_capas", "description": "Recoge al menos un dato lateral regalado por el cliente y construye sobre él con las palabras del cliente."}, {"id": "mindset.rrr", "weight": 0.15, "regla_id": "discovery.rrr", "description": "Lee la prisa del cliente, la reconoce verbalmente con naturalidad y ajusta su ritmo — directo y sin rodeos, respetando el estado."}, {"id": "blocks.air", "weight": 0.15, "regla_id": "blocks.air", "description": "Atraviesa el bloqueo con la secuencia completa: agree breve, ignore total del tema, resume por hilo natural."}, {"id": "story.historia_breve", "weight": 0.1, "regla_id": "story.quien_eres_por_que", "description": "Historia breve correcta en su momento: quién es + por qué está ahí, corta, con gancho."}]}$g$::jsonb WHERE id = '3.10' AND practice_script->>'version' = '1.0.1';
UPDATE public.nodes SET practice_script = $g${"notes": "BOSS del Mundo 7 contra el desconfiado d5 — el examen integrador de las dos especies del no: bloqueo (AIR) y objeciones (reframe+balas) en la misma conversación. Mecánicas distintivas: la minimización del dolor (capa extra sobre M3), la objeción de confianza PERSONAL (la más difícil de no tomar como ataque), y la condición de protección que se honra en vez de pelearse. Su rendición característica — le tomo la palabra y lo apunto — es la victoria realista: confianza a prueba, no fe ciega. v1.1.0 (oct-2026, Emilio): el boss de El Cierre califica con los nombres de la doctrina: RRR para la objeción menor, FFF para la de confianza, balas y círculo de cierre. \"Sin defensa\" sale de los criterios porque ya es falla crítica.", "scope": {"skills_in_focus": ["blocks.air", "objections.rrr_objeciones", "objections.reframe", "objections.bullet_theory", "objections.circulo_cierre", "discovery.dolor_real", "closing.cierre_asumido"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 20, "max_duration_seconds": 480, "min_turns_before_evaluation": 8}, "phases": {"you_do": {"prompt": "Eres el dueño de un negocio de perfil DESCONFIADO EXTREMO: años de vendedores que prometieron y fallaron te dejaron un escudo grueso — no eres grosero, eres impenetrable por default. GUION COMPLETO: (1) BLOQUEO de entrada en tu primera o segunda respuesta: mire, le voy a ahorrar tiempo — no me interesa. Espejo AIR estándar: bien atravesado sigues (seco); debatido, te cierras más. (2) DOLOR oculto (elige: proveedor que te falla quincenalmente / dinero muerto en producto parado / algo que piden y no consigues) — por capas, con pista del aunque, y una capa EXTRA de desconfianza: al revelarlo, lo minimizas de inmediato (pero bueno, así es esto, todos fallan igual) — el vendedor debe validar que NO es normal y cuantificarlo para que lo tomes en serio. (3) PRESENTACIÓN: toda promesa sin ancla dispara tu cicatriz (eso mismo me dijo el anterior); solo el valor conectado con TU dolor y TUS números te abre. (4) CADENA DE OBJECIONES — tu examen final, DOS en serie tras la presentación: primera siempre: ¿y por qué le voy a creer a usted, si el anterior me dijo lo mismo y me dejó plantado? (objeción de confianza — pide bala SOBRE ÉL: constancia verificable, referencia de la zona con nombre). Segunda: una objeción MENOR y común, al azar: está caro / el día de entrega no me acomoda. Se atiende con RRR: si te la repite, te responde concreto y sigue, la sueltas; si se pone a discutirla, te cansas. Espejos completos de 7.2/7.3: defensa te atrinchera, evasión la señalas, bala vaga la retas (¿como quién? voy a ir a preguntarle, ¿eh?), cargador vaciado te abruma, bala repetida no te convence. (5) Si TODO se sostuvo: tu rendición es característica — está bien... pero le voy a tomar la palabra de todo lo que dijo, ¿eh? Lo apunto. — y avanzas con UNA condición de protección (pedido chico de prueba / por escrito / referencia confirmada antes). Deliberación final con pausa — espejo de silencio del 6.3. Tu techo: trato de prueba cerrado, nunca confianza plena — esa se gana en meses, no en una visita. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.", "objective": "El vendedor completa la conversación con el desconfiado extremo: atraviesa el bloqueo con AIR, excava el dolor Y desmonta su minimización cuantificándolo, presenta sin una sola promesa sin ancla, sostiene la cadena de dos objeciones — la de confianza personal con bala sobre sí mismo verificable, y la segunda con su munición propia — con temple idéntico, y cierra asumido aceptando la condición de protección del cliente, aguantando la deliberación final. El scope se cubre con el trato de prueba cerrado."}, "closing": {"message": "El hombre que no le cree a nadie te acaba de tomar la palabra — y la apuntó. Atravesaste su bloqueo, desmontaste su resignación, y cada bala tuya aguantó su lupa. No ganaste su confianza completa: ganaste algo mejor — la oportunidad de demostrarla. Así maneja al más duro del campo. Vamos al desglose del mundo.", "message_incomplete": "Hasta aqui la sesion. Ya tengo lo que necesito para tu analisis. Vamos al desglose."}}, "version": "1.1.1", "i_do_type": "demo", "failure_criteria": [{"id": "se_pone_defensivo", "regla_id": "objection.discutir", "severity": "critical", "description": "La objeción personal lo hiere y se defiende — el desconfiado confirma su tesis y se cierra para siempre."}, {"id": "impulso_falso", "regla_id": "present.bala_generica", "severity": "critical", "description": "Cualquier bala o promesa inventada — el desconfiado VA a verificar (voy a ir a preguntarle, ¿eh?) y este arquetipo no da segundas oportunidades.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "promesa_grandilocuente", "regla_id": "present.bala_generica", "severity": "critical", "description": "Promesas sin ancla ante la cicatriz — eso mismo me dijo el anterior, y la sesión retrocede.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "air_a_objecion", "regla_id": "objection.air_a_objecion", "severity": "critical", "description": "Evade cualquier objeción de la cadena con cambio de tema."}, {"id": "traga_la_minimizacion", "regla_id": "discovery.confirmacion_con_sus_palabras", "severity": "major", "description": "Acepta el pero así es esto, todos fallan igual sin desmontarlo — el dolor queda archivado como normal y la venta pierde su motor.", "espejo_de": "discovery.dolor_real"}, {"id": "pelea_la_condicion", "regla_id": "discovery.presiona_compromiso", "severity": "major", "description": "Pelea la condición de protección del cliente (empuja el pedido grande, resiste el por escrito) — la condición era el puente, y lo quemó.", "severity_override": {"razon": "incidental: error de otro paso", "default": "critical"}}, {"id": "vacia_el_cargador", "regla_id": "objection.vacia_el_cargador", "severity": "major", "description": "Apila argumentos bajo presión."}, {"id": "llena_el_silencio", "regla_id": "close.llena_el_silencio", "severity": "major", "description": "No aguanta la deliberación final."}, {"id": "insiste_tras_dos", "regla_id": "blocks.insistir_tras_dos_no", "severity": "major", "description": "Después de dos no seguidos en la puerta sigue insistiendo: pide un minutito, vuelve a su tema o trata de convencerlo, en vez de quedar de regresar en otro momento. Ya no es seguridad, es terquedad. Solo cuenta lo que dice DESPUÉS del segundo no seguido."}], "success_criteria": [{"id": "blocks.air", "weight": 0.15, "regla_id": "blocks.air", "description": "El bloqueo de entrada atravesado con la secuencia completa — la distinción bloqueo/objeción ejecutada en ambas direcciones dentro de la misma conversación."}, {"id": "objections.rrr_objeciones", "weight": 0.15, "regla_id": "objection.rrr", "description": "La segunda objeción, menor y común (precio o entrega), atendida con RRR: la repite en sus términos, responde concreto, y retoma sin pausa."}, {"id": "objections.reframe", "weight": 0.2, "regla_id": "objection.fff", "description": "La objeción de confianza (¿por qué le voy a creer a usted?) recibida con FFF: sin herida ni defensa, entiende cómo se siente, otros sintieron lo mismo, lo que encontraron, con una bala sobre sí mismo verificable."}, {"id": "objections.bullet_theory", "weight": 0.15, "regla_id": "present.balas", "description": "Munición precisa bajo lupa: bala SOBRE SÍ MISMO verificable para la objeción de confianza (constancia, nombre, referencia comprobable), bala distinta para la segunda — todas aguantando el ¿como quién?"}, {"id": "objections.circulo_cierre", "weight": 0.15, "regla_id": "objection.circulo_de_cierre", "description": "Después de atravesar cada objeción, re-impulsa con una bala NUEVA y vuelve a pedir la decisión con acción."}, {"id": "discovery.dolor_real", "weight": 0.1, "regla_id": "discovery.confirmacion_con_sus_palabras", "description": "El dolor excavado por capas Y su minimización desmontada: valida que no es normal y lo cuantifica con los números del cliente hasta que lo tome en serio."}, {"id": "closing.cierre_asumido", "weight": 0.1, "regla_id": "close.alternativa", "description": "Cierra asumido aceptando con gracia la condición de protección (pedido de prueba, por escrito) — la condición no se pelea: se honra como el puente de confianza que es."}]}$g$::jsonb WHERE id = '5.15' AND practice_script->>'version' = '1.1.0';
UPDATE public.nodes SET practice_script = $g${"notes": "EXAMEN 1 de la Certificación. Cliente realista completo (todas las mecánicas activas, sin espejo pedagógico suave): bloqueo posible, dolor por capas, FORMD, objeción real posible, señal de compra, deliberación y duda latente post-sí. Los 6 pasos pesan en el score. Sin i_do — el mundo 9 no enseña: examina.", "scope": {"skills_in_focus": ["opening.estructura_apertura", "story.historia_breve", "blocks.air", "flow.close_with_action", "discovery.dolor_real", "presentation.conectar_dolor", "closing.cierre_asumido", "consolidation.proteger_venta"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 20, "max_duration_seconds": 480, "min_turns_before_evaluation": 8}, "phases": {"you_do": {"prompt": "Eres el dueño de un negocio — un cliente REALISTA y completo, sin guion pedagógico: reaccionas a lo que el vendedor haga, bien o mal, como reaccionaría un dueño de verdad. PERFIL (elige al azar y mantenlo): (A) práctico y directo, algo escéptico; (B) cordial pero distraído con el negocio encima; (C) reservado que se abre solo con quien se lo gana. CONFIGURACIÓN REALISTA COMPLETA: (1) Puedes soltar un bloqueo reflejo temprano si el momento lo pide (ando ocupado / hoy no ando viendo nada) — espejo AIR estándar. (2) Tienes un DOLOR REAL (elige: faltantes quincenales / dinero muerto en producto parado / línea pedida que no consigues) revelable solo por capas con la pista del aunque. (3) Tienes vida (1 elemento FORMD si el vendedor la toca con genuinidad). (4) Puedes soltar UNA objeción real post-presentación si algo no te convence (precio o proveedor actual) — se honra con reframe, no con AIR. (5) Sueltas una señal de compra cuando el valor te convenza — quien la cosecha cierra, quien sigue presentando te enfría. (6) Al cierre asumido bien puesto respondes eligiendo opción, con deliberación breve si te nace. (7) POST-SÍ: tienes una duda latente (¿cuándo llega exactamente?) — aflora insegura si el vendedor celebra y corre; muere si consolida con próximos pasos claros. Tu techo: trato cerrado y tranquilo, con siguiente visita clara.", "objective": "El vendedor conduce los 6 pasos completos: apertura con estructura y personalización, historia breve con gancho, descubrimiento por capas hasta el dolor confirmado, presentación conectada con al menos una imagen y síes genuinos, cierre asumido cosechado en el momento correcto, y consolidación con próximos pasos cristalinos que dejan al cliente tranquilo y la siguiente visita puesta. El scope se cubre cuando la venta quedó cerrada Y consolidada — el cliente repitió los términos con tranquilidad."}, "closing": {"message": "De la puerta al apretón de manos — los seis pasos, sin ayuda, con un cliente de verdad. El sistema ya no es un mapa que sigues: es cómo conversas. Primer examen aprobado. Vamos al desglose.", "message_incomplete": "Hasta aqui el examen. Vamos al desglose."}}, "version": "1.1.2", "i_do_type": "demo", "failure_criteria": [{"id": "pitch_prematuro", "regla_id": "discovery.receta_sin_diagnostico", "severity": "critical", "description": "Presenta antes de excavar y confirmar el dolor.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "abre_puerta_al_no", "regla_id": "close.mal_cierre", "severity": "major", "description": "Cierra con pregunta de interés o propone el aplazamiento.", "severity_override": {"razon": "incidental: error de otro paso", "default": "critical"}}, {"id": "sigue_presentando", "regla_id": "close.sigue_presentando", "severity": "major", "description": "Deja pasar la señal de compra por seguir con el guion."}, {"id": "celebra_y_corre", "regla_id": "consolidation.sigue_vendiendo", "severity": "major", "description": "Tras el sí, celebra y se va sin consolidar — la duda latente aflora y la venta queda sembrada de remordimiento.", "severity_override": {"razon": "incidental: error de otro paso", "default": "critical"}}, {"id": "debate_bloqueo", "regla_id": "blocks.discute_bloqueo", "severity": "critical", "description": "Argumenta el bloqueo en lugar de atravesarlo con AIR.", "severity_fix": "major->critical (BOSS no baja errores de su paso)"}, {"id": "se_defiende", "regla_id": "objection.discutir", "severity": "critical", "description": "Responde la objeción real contradiciendo o defendiéndose en lugar de validar + reframe.", "severity_fix": "major->critical (BOSS no baja errores de su paso)"}, {"id": "presentacion_generica", "regla_id": "present.dos_mitades", "severity": "critical", "description": "Presenta catálogo sin conectar con el dolor excavado.", "severity_override": {"default": "major", "razon": "Certificación: presentar sin conectar con el dolor no puede aprobar un examen (decisión de Emilio, oct-2026)"}}, {"id": "monologo", "regla_id": "monologo", "severity": "minor", "description": "Bloques largos que atropellan la conversación."}, {"id": "insiste_tras_dos", "regla_id": "blocks.insistir_tras_dos_no", "severity": "major", "description": "Después de dos no seguidos en la puerta sigue insistiendo: pide un minutito, vuelve a su tema o trata de convencerlo, en vez de quedar de regresar en otro momento. Ya no es seguridad, es terquedad. Solo cuenta lo que dice DESPUÉS del segundo no seguido."}], "success_criteria": [{"id": "opening.estructura_apertura", "weight": 0.1, "regla_id": "opening.estructura", "description": "Apertura completa y calibrada: saludo + observación específica + una pregunta que cierre el turno y le devuelva la palabra, sin producto, con seguridad tipo gasman."}, {"id": "story.historia_breve", "weight": 0.1, "regla_id": "story.quien_eres_por_que", "description": "Historia breve correcta en su momento: quién es + por qué está ahí, corta, humana, con gancho que devuelve la palabra."}, {"id": "blocks.air", "weight": 0.1, "regla_id": "blocks.air", "description": "Si aparece un bloqueo reflejo, lo atraviesa con AIR: lo acepta, no lo pelea, y sigue con la plática. Si en la conversación no hay bloqueo, este criterio es no_aplica."}, {"id": "flow.close_with_action", "weight": 0.1, "regla_id": "close_with_action", "description": "Mantiene viva la conversación: sus turnos devuelven la palabra con una pregunta, y después de cada freno avanza por su cuenta sin esperar permiso."}, {"id": "discovery.dolor_real", "weight": 0.15, "regla_id": "discovery.confirmacion_con_sus_palabras", "description": "Descubrimiento por capas hasta el dolor completo, revelado por el cliente y confirmado verbalmente antes de presentar."}, {"id": "presentation.conectar_dolor", "weight": 0.15, "regla_id": "present.dos_mitades", "description": "Presentación construida sobre el dolor confirmado: el puente dolor→solución explícito, con valor personalizado y al menos una imagen o tren de síes."}, {"id": "closing.cierre_asumido", "weight": 0.15, "regla_id": "close.alternativa", "description": "Cierre asumido con opciones en el momento del pico — sin puertas al no, cosechando la señal si apareció."}, {"id": "consolidation.proteger_venta", "weight": 0.15, "regla_id": "consolidation.siguientes_pasos", "description": "Consolidación post-sí: próximos pasos cristalinos (qué, cuándo, cómo), la duda latente muerta antes de nacer, y la siguiente visita puesta."}]}$g$::jsonb WHERE id = '7.0' AND practice_script->>'version' = '1.1.1';
UPDATE public.nodes SET practice_script = $g${"notes": "BOSS FINAL — arquetipo agresivo/hostil d5, sin restricciones: bloqueo de entrada + objeciones encadenadas + regateo + silencio, la conversación más larga y dura del mapa (22 turnos). REGLA DE CERTIFICACIÓN para el Progression Engine: este nodo certifica con score ≥ 85 — un pase menor completa el nodo pero NO otorga la certificación (se repite hasta lograrlo; las estrellas guardan el mejor intento como siempre). Al certificar: Certificación Closer + desbloqueo de la Etapa 2 (coaching por números reales de campo).", "scope": {"skills_in_focus": ["blocks.air", "discovery.dolor_real", "presentation.conectar_dolor", "objections.reframe", "closing.cierre_asumido", "closing.sin_miedo", "impulse.indiferencia", "consolidation.proteger_venta"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 22, "max_duration_seconds": 540, "min_turns_before_evaluation": 10}, "phases": {"you_do": {"prompt": "Eres el dueño de un negocio de perfil HOSTIL-ESCÉPTICO — el cliente más difícil del mapa: seco, cortante, sin paciencia para vendedores, con regateo agresivo en la sangre. NO eres grosero gratuito: eres un hueso duro que respeta solo la excelencia. GUION COMPLETO: (1) BLOQUEO de entrada, cortante apenas llega (no, gracias — siguiente puerta). Si lo atraviesa con AIR limpio, NO repites el bloqueo: dos no seguidos en la puerta y el vendedor debería irse. En su lugar sueltas, con fastidio, una objeción de entrada que sí deja por dónde seguir (a ver, ¿y usted qué trae? ándele, que ando con prisa) — atravesar el bloqueo y responder sin quebrarse ni disculparse es el precio de entrada. (2) Tu DOLOR REAL existe (elige: faltantes del producto estrella que te cuestan clientes cada quincena / línea muy pedida que tu proveedor no maneja) — revelable SOLO por capas y solo ante preguntas de calidad: a las preguntas flojas respondes con sarcasmo seco (¿y a usted eso qué le importa?). (3) A la presentación respondes con OBJECIONES ENCADENADAS — mínimo dos de estas tres, en serio y con contenido: está caro (y lo comparas con números), ya tengo proveedor de años (y lo defiendes), ¿y por qué le voy a creer a usted? — cada una se honra con reframe + evidencia; la defensividad o el descuento de pánico te dan la razón y aprietas más. (4) Señal de compra tardía y seca cuando el valor de verdad te haya ganado (¿cuál es el pedido mínimo?). (5) Al cierre asumido: REGATEO final agresivo (bájele un diez por ciento y cerramos ahorita) — espejo: descuento de pánico = hueles sangre y pides más; firmeza estructurada = respeto seco. (6) Deliberación final EN SILENCIO largo (mmm... a ver... deme un segundo...) — quien lo llena, pierde el trato; quien lo aguanta, escucha tu decisión: va. Pero me cumple, ¿eh? (7) POST-SÍ: una sola pregunta seca de consolidación (¿y cuándo llega?) — próximos pasos cristalinos o tu confianza recién nacida tiembla. Tu techo: trato cerrado seco con advertencia — me cumple, ¿eh?. Nunca calidez.", "objective": "El vendedor ejecuta el sistema completo bajo presión máxima: atraviesa el bloqueo de entrada con AIR sin quebrarse, excava el dolor con preguntas de calidad ante la hostilidad, presenta conectado, honra las objeciones encadenadas con reframe y evidencia (sin defensividad ni descuentos), cosecha la señal tardía con cierre asumido, sostiene el regateo con firmeza estructurada, aguanta el silencio final completo, y consolida con próximos pasos cristalinos. El scope se cubre cuando el trato quedó cerrado y consolidado — con el me cumple, ¿eh? del cliente como sello."}, "closing": {"message": "El cliente más difícil del mapa acaba de decirte me cumple, ¿eh? — que en su idioma significa: confío en usted. Bloqueo de entrada, objeciones en serie, regateo, silencio... y el sistema completo aguantó. Esto era la certificación. Vamos al desglose final.", "message_incomplete": "Hasta aqui el examen final. Vamos al desglose."}}, "version": "1.0.2", "i_do_type": "demo", "failure_criteria": [{"id": "se_derrumba", "regla_id": "impulse.indiferencia", "severity": "critical", "description": "La hostilidad lo quiebra en cualquier punto: se disculpa, se apresura, se enfría o abandona la estructura — el examen entero es no quebrarse.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "descuento_de_panico", "regla_id": "close.descuento_de_panico", "severity": "critical", "description": "Cede al regateo sin estructura — el hueso duro huele sangre y el trato pierde piso.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "impulso_falso", "regla_id": "present.bala_generica", "severity": "critical", "description": "Cualquier invento bajo presión — datos, urgencias o promesas falsas para sobrevivir la hostilidad.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "se_defiende", "regla_id": "objection.discutir", "severity": "critical", "description": "Responde las objeciones contradiciendo o defendiéndose en lugar de validar + reframe.", "severity_fix": "major->critical (BOSS no baja errores de su paso)"}, {"id": "llena_el_silencio", "regla_id": "close.llena_el_silencio", "severity": "major", "description": "No aguanta la deliberación final — el trato que ya era suyo se le escapa de la boca."}, {"id": "debate_bloqueo", "regla_id": "blocks.discute_bloqueo", "severity": "critical", "description": "Argumenta el bloqueo de entrada en lugar de atravesarlo.", "severity_fix": "major->critical (BOSS no baja errores de su paso)"}, {"id": "abre_puerta_al_no", "regla_id": "close.mal_cierre", "severity": "major", "description": "Cierra con pregunta de interés — a este cliente, la puerta abierta no se le ofrece dos veces.", "severity_override": {"razon": "incidental: error de otro paso", "default": "critical"}}, {"id": "monologo", "regla_id": "monologo", "severity": "minor", "description": "Bloques largos ante un cliente sin paciencia."}, {"id": "insiste_tras_dos", "regla_id": "blocks.insistir_tras_dos_no", "severity": "major", "description": "Después de dos no seguidos en la puerta sigue insistiendo: pide un minutito, vuelve a su tema o trata de convencerlo, en vez de quedar de regresar en otro momento. Ya no es seguridad, es terquedad. Solo cuenta lo que dice DESPUÉS del segundo no seguido."}], "success_criteria": [{"id": "blocks.air", "weight": 0.12, "regla_id": "blocks.air", "description": "Atraviesa el bloqueo de entrada con AIR limpio y sostiene el fastidio que viene después — sin quebrarse, disculparse ni debatir, con la calidez intacta."}, {"id": "discovery.dolor_real", "weight": 0.13, "regla_id": "discovery.confirmacion_con_sus_palabras", "description": "Excava el dolor con preguntas de calidad que aguantan el sarcasmo — hasta la revelación y confirmación."}, {"id": "presentation.conectar_dolor", "weight": 0.12, "regla_id": "present.dos_mitades", "description": "Presentación construida sobre el dolor confirmado, personalizada y sin promesas grandilocuentes."}, {"id": "objections.reframe", "weight": 0.15, "regla_id": "objection.fff", "description": "Las objeciones encadenadas se honran una por una: validación + evidencia concreta + avance — sin defensividad, sin contradecir, sin ceder por cansancio."}, {"id": "closing.cierre_asumido", "weight": 0.12, "regla_id": "close.alternativa", "description": "Cosecha la señal tardía con cierre asumido de opciones — sin puertas al no en todo el tramo final."}, {"id": "closing.sin_miedo", "weight": 0.13, "regla_id": "close.aguanta_silencio", "description": "Sostiene el regateo con firmeza estructurada (cero descuentos de pánico) y aguanta el silencio final completo sin llenarlo."}, {"id": "impulse.indiferencia", "weight": 0.12, "regla_id": "impulse.indiferencia", "description": "SW3 de principio a fin ante la hostilidad: sereno, sin perseguir, sin ansiedad — el hueso duro solo respeta al que no se quiebra."}, {"id": "consolidation.proteger_venta", "weight": 0.11, "regla_id": "consolidation.siguientes_pasos", "description": "Consolida el sí seco con próximos pasos cristalinos — la confianza recién nacida queda protegida."}]}$g$::jsonb WHERE id = '7.4' AND practice_script->>'version' = '1.0.1';

DO $chk$ DECLARE v int; n int; BEGIN
  SELECT max(version) INTO v FROM public.doctrina WHERE is_active;
  IF (SELECT count(*) FROM public.doctrina WHERE is_active) <> 7 THEN RAISE EXCEPTION 'el Cerebro no tiene 7 secciones activas'; END IF;
  IF (SELECT count(DISTINCT version) FROM public.doctrina WHERE is_active) <> 1 THEN RAISE EXCEPTION 'hay más de una versión activa del Cerebro'; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE is_active AND strpos(body, $v$**Dos no seguidos** `CAMPO`: en cualquier momento de la visita, menos en el cierre, dos «no» seguidos son la señal de que hoy no es el día, y lo correcto es dejarlo para otra visita. En la puerta: si haces AIR y el cliente repite el bloqueo de inmediato, ya son dos no seguidos. Ahí lo correcto es quedar de regresar en otro momento, con una alternativa concreta: *"¿le queda mejor que pase el jueves o el viernes?"*. Insistir más ya no es seguridad: es terquedad. Al buscar el hueco es igual: si dos intentos seguidos se topan con un «no», dejas de buscar y lo retomas en otra visita. Tienen que ser consecutivos: si la conversación avanzó entre uno y otro, el primero ya quedó atrás. En el cierre la regla es otra: son tres (ver La Regla de los No).

**Qué es un «no»** `CAMPO`: una respuesta que rechaza lo que el vendedor estaba intentando en ese momento —seguir la plática, explorar ese tema o avanzar a la decisión—, aunque traiga excusa. Una respuesta, aunque sea vaga o corta, no es un «no»: no rechazó nada, y lo que toca es seguir. Una duda, una condición o una objeción tampoco es un «no»: es una objeción, y se trabaja con sus herramientas.$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro no recibió: %', $v$**Dos no seguidos** `CAMPO`: en cualquier momento de la visita, menos $v$; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE is_active AND strpos(body, $v$- **Esta regla es del cierre.** En cualquier otro momento de la visita son **dos** no seguidos: en la puerta quedas de regresar, y al buscar el hueco lo dejas para otra visita (ver Dos no seguidos, en AIR).$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro no recibió: %', $v$- **Esta regla es del cierre.** En cualquier otro momento de la visita$v$; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE is_active AND strpos(body, $v$> **La línea que no se cruza:** un hueco tiene que ser real y verificable. **Descubrir un hueco es señalar algo que ya existe. Fabricarlo es venderle un problema que no tiene.**

**Si no hay hueco** `CAMPO`: si lo buscaste bien —con las herramientas, y siguiendo las respuestas vagas— y no apareció, o te topaste con dos «no» seguidos, hoy no había nada que descubrir. No es una falla: lo retomas en otra visita.$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro no recibió: %', $v$> **La línea que no se cruza:** un hueco tiene que ser real y verifica$v$; END IF;
  SELECT count(*) INTO n FROM public.reglas r WHERE EXISTS (SELECT 1 FROM public.doctrina d WHERE d.version = v - 1 AND strpos(d.body, r.cita_cerebro) > 0) AND NOT EXISTS (SELECT 1 FROM public.doctrina d WHERE d.version = v AND strpos(d.body, r.cita_cerebro) > 0);
  IF n > 0 THEN RAISE EXCEPTION '% citas de reglas ya no están en el Cerebro', n; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'flow.dos_no_seguidos' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'falta la regla flow.dos_no_seguidos o su cita'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'objection.regla_de_los_no') IS DISTINCT FROM $v$Tres no CONSECUTIVOS y sigues adelante. La racha se rompe si la conversación avanza. Solo en el cierre: en cualquier otro momento de la visita son dos (flow.dos_no_seguidos).$v$ THEN RAISE EXCEPTION 'la regla objection.regla_de_los_no no quedó'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'objections.regla_de_los_no') IS DISTINCT FROM $v$La Regla de los No: tres 'no' CONSECUTIVOS son luz roja (la fuente dice dos; Emilio usa tres, porque hay quien deja ir un sí solo porque el cliente tuvo objeciones). Con la luz roja, el vendedor sale rápido y bien: sin insistir, cuidando la relación y dejando una siguiente cita. Tienen que ser seguidos: si la conversación avanzó entre un no y otro, la racha se rompe. Salir así es la ejecución correcta, no una falta. Esta regla es del cierre: en cualquier otro momento de la visita son dos no seguidos (flow.dos_no_seguidos).$v$ THEN RAISE EXCEPTION 'la regla objections.regla_de_los_no no quedó'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'discovery.hueco') IS DISTINCT FROM $v$El hueco es algo que el cliente podría comprarte y no te compra: una familia que le compra a otro proveedor, una que le piden y no maneja, o una que no maneja nadie. No tiene señal verbal: se ve o se pregunta. Tiene que ser real y verificable: lo viste, te lo dijo, o lo sabes por su giro. LA PRUEBA: al terminar la plática, ¿quedó al descubierto al menos un hueco concreto —una familia con nombre— porque el vendedor lo preguntó, lo vio, lo ancló en negocios como el suyo, o el cliente lo dijo? Si sí, cumple, aunque el vendedor no lo mencione: el hueco se descubre y se apunta para usarlo en la presentación. No basta con preguntar si la respuesta no dejó ninguna familia concreta. Ofrecérselo o decirle por qué le conviene no se pide aquí: eso es presentar el hueco (paso 4). Si el vendedor lo buscó bien —usó las herramientas y siguió las respuestas vagas— o salió después de dos «no» seguidos, y no apareció ningún hueco, el criterio es no_aplica: hoy no había nada que descubrir.$v$ THEN RAISE EXCEPTION 'la regla discovery.hueco no quedó'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'develop.visita_tramite') IS DISTINCT FROM $v$Levantar el pedido de siempre y despedirse sin explorar nada. Al que solo toma pedidos lo reemplaza un formulario. LA PRUEBA: ¿el vendedor se fue con el pedido sin haber descubierto algo más y sin haberlo intentado de verdad? Intentarlo es usar al menos una de las herramientas del hueco —mapear qué otras líneas maneja y con quién, preguntar qué le piden que no tenga, o anclar en negocios como el suyo— y, si la respuesta es vaga («de todo un poco», «lo normal»), seguir: con opciones concretas o con otra herramienta. Una sola pregunta al aire y despedirse después de una respuesta vaga es trámite. Si descubrió algo más, o lo intentó así, no es esto. Dejar de buscar después de dos «no» seguidos no es trámite: es lo correcto (flow.dos_no_seguidos).$v$ THEN RAISE EXCEPTION 'la regla develop.visita_tramite no quedó'; END IF;
  IF (SELECT severidad_default FROM public.reglas WHERE id = 'blocks.insistir_tras_dos_no') IS DISTINCT FROM 'major' THEN RAISE EXCEPTION 'la severidad de blocks.insistir_tras_dos_no no quedó'; END IF;
  IF (SELECT md5(practice_script::text) FROM public.nodes WHERE id = '2.7c') IS DISTINCT FROM 'b05ef53d8e6b03e84d6d488d9cbf0395' THEN RAISE EXCEPTION 'el guion del 2.7c no quedó'; END IF;
  IF (SELECT md5(practice_script::text) FROM public.nodes WHERE id = '2.10') IS DISTINCT FROM 'd9d6d80ad64b32b5e394d75239a108ca' THEN RAISE EXCEPTION 'el guion del 2.10 no quedó'; END IF;
  IF (SELECT md5(practice_script::text) FROM public.nodes WHERE id = '3.10') IS DISTINCT FROM '4a67f6f63fdc773815de161fc399358e' THEN RAISE EXCEPTION 'el guion del 3.10 no quedó'; END IF;
  IF (SELECT md5(practice_script::text) FROM public.nodes WHERE id = '5.15') IS DISTINCT FROM 'c8d56cd467fa879b4ac99df31bf5e3d9' THEN RAISE EXCEPTION 'el guion del 5.15 no quedó'; END IF;
